<?php
require dirname(__DIR__).'/lib/bootstrap.php';
use davvag_events\{Support,Domain,Seating,Fault};
$checks=0;
function seatCheck($ok,$label){global $checks;if(!$ok)throw new RuntimeException('FAILED: '.$label);$checks++;echo 'PASS '.$label.PHP_EOL;}
function seatReject($code,$fn,$label){try{$fn();}catch(Fault $f){seatCheck($f->reason===$code,$label);return;}throw new RuntimeException('Expected '.$code.': '.$label);}
function seatingEvent(){return Domain::create(['occasion'=>'wedding','title'=>'Fictional seating test','timezone'=>'UTC','start'=>'2027-06-12T12:00:00Z','end'=>'2027-06-12T20:00:00Z','venue'=>'Fictional hall','capacity'=>100],'owner');}
function section(&$e,$label){Seating::saveSection($e,['layoutRevision'=>$e['layoutRevision'],'label'=>$label,'color'=>'#446688']);return $e['seatingSections'][count($e['seatingSections'])-1]['id'];}
function table(&$e,$cap=4,$section='',$shape='round'){return Seating::saveTable($e,['layoutRevision'=>$e['layoutRevision'],'capacity'=>$cap,'shape'=>$shape,'sectionId'=>$section]);}
function guests(&$e,$names){$p=Domain::addParty($e,['names'=>$names,'group'=>'Family']);foreach($e['guests'] as &$g)$g['rsvp']='Attending';unset($g);return array_column($e['guests'],'id');}
$e=seatingEvent();$input=['layoutRevision'=>0,'action'=>'addTables','operation'=>Support::id(),'count'=>3,'capacity'=>4,'shape'=>'round','number'=>1];$r=Seating::change($e,$input);seatCheck($r['created']===3&&array_column($e['tables'],'number')===[1,2,3],'popup can add sequentially numbered tables');seatCheck(array_column($e['tables'][0]['seats'],'label')===['1','2','3','4'],'table seats are numbered automatically');
$input['layoutRevision']=$e['layoutRevision'];$repeat=Seating::change($e,$input);seatCheck($repeat===$r&&count($e['tables'])===3,'same table creation operation does not duplicate tables');seatCheck(Seating::nextNumber($e)===4,'next table number follows existing numbers');
foreach(['oval','square','rectangle'] as $shape){$t=table($e,6,'',$shape);seatCheck($t['shape']===$shape,'supports '.$shape.' table shape');}
seatReject('TABLE_NUMBER',function()use($e){$copy=$e;Seating::saveTable($copy,['layoutRevision'=>$copy['layoutRevision'],'number'=>1]);},'duplicate table number rejected');
$ids=guests($e,['Guest One','Guest Two']);$seatId=$e['tables'][0]['seats'][0]['id'];Seating::assign($e,['layoutRevision'=>$e['layoutRevision'],'guestId'=>$ids[0],'seatId'=>$seatId]);$oldSeats=array_column($e['tables'][0]['seats'],'id');$edited=Seating::saveTable($e,['layoutRevision'=>$e['layoutRevision'],'tableId'=>$e['tables'][0]['id'],'shape'=>'oval','capacity'=>6]);seatCheck(array_slice(array_column($edited['seats'],'id'),0,4)===$oldSeats&&$e['assignments'][0]['seatId']===$seatId,'changing shape/capacity preserves existing seat IDs and assignments');
seatReject('OCCUPIED',function()use($e){$copy=$e;Seating::saveTable($copy,['layoutRevision'=>$copy['layoutRevision'],'tableId'=>$copy['tables'][0]['id'],'delete'=>true]);},'occupied table needs explicit release before removal');
$copy=$e;Seating::saveTable($copy,['layoutRevision'=>$copy['layoutRevision'],'tableId'=>$copy['tables'][0]['id'],'delete'=>true,'releaseOccupied'=>true]);seatCheck(count($copy['assignments'])===0&&count($copy['guests'])===2,'confirmed removal releases seats and preserves guests');
seatReject('LAYOUT_STALE',function()use($e){$copy=$e;Seating::change($copy,['layoutRevision'=>0,'action'=>'section','label'=>'Stale']);},'stale layout cannot change a section');
seatReject('SEAT',function()use($e){$copy=$e;Seating::saveTable($copy,['layoutRevision'=>$copy['layoutRevision'],'capacity'=>4,'accessibleSeats'=>[0]]);},'invalid accessible-seat positions rejected');
$family=section($e,'Family area');$balcony=section($e,'Balcony');$t=table($e,4,$family);seatCheck($t['sectionId']===$family,'table belongs to its selected section');
seatReject('SECTION',function()use($e){$copy=$e;Seating::saveTable($copy,['layoutRevision'=>$copy['layoutRevision'],'sectionId'=>Support::id()]);},'cross-event/unknown section rejected');
seatReject('SECTION',function()use($e){$copy=$e;Seating::saveSection($copy,['layoutRevision'=>$copy['layoutRevision'],'label'=>'Family area']);},'duplicate section name rejected');
$rowInput=['layoutRevision'=>$e['layoutRevision'],'action'=>'addRows','operation'=>Support::id(),'rows'=>2,'seatsPerRow'=>3,'firstRow'=>'A','numbering'=>'perRow','sectionId'=>$balcony,'accessible'=>true];$rows=Seating::change($e,$rowInput);$tail=array_slice($e['tables'],-2);seatCheck($rows['seats']===6&&array_column($tail[0]['seats'],'label')===['A1','A2','A3']&&array_column($tail[1]['seats'],'label')===['B1','B2','B3'],'seat plan creates lettered rows with numbered seats');seatCheck($tail[0]['seats'][0]['accessible']&&!$tail[0]['seats'][1]['accessible'],'numbered plan can provide accessible first seats');
$beforeRetry=count($e['tables']);$rowInput['layoutRevision']=$e['layoutRevision'];Seating::change($e,$rowInput);seatCheck(count($e['tables'])===$beforeRetry,'seat plan retry does not create duplicate rows');
$rowInput['operation']=Support::id();$rowInput['layoutRevision']=$e['layoutRevision'];seatReject('ROW',function()use($e,$rowInput){$copy=$e;Seating::change($copy,$rowInput);},'duplicate row labels within a section are rejected');
$continuous=seatingEvent();Seating::addRows($continuous,['layoutRevision'=>0,'operation'=>Support::id(),'rows'=>2,'seatsPerRow'=>2,'firstRow'=>'Z','numbering'=>'continuous','startNumber'=>10]);seatCheck($continuous['tables'][0]['label']==='Row Z'&&$continuous['tables'][1]['label']==='Row AA'&&array_column($continuous['tables'][1]['seats'],'label')===['12','13'],'continuous numbering and row labels beyond Z work');
$groupEvent=seatingEvent();$guestIds=guests($groupEvent,['Family One','Family Two']);$front=section($groupEvent,'Front');$rear=section($groupEvent,'Rear');$small=table($groupEvent,1,$front);$other=table($groupEvent,2,$rear);
Seating::saveGroup($groupEvent,['layoutRevision'=>$groupEvent['layoutRevision'],'label'=>'Family','originalLabel'=>'Family','guestIds'=>$guestIds,'keepTogether'=>true,'sectionId'=>$front,'color'=>'#994455']);$group=$groupEvent['groups'][0];$plan=Seating::plan($groupEvent,['allowSplit'=>true]);seatCheck(count($plan['assignments'])===0&&count($plan['unsatisfied'])===1,'group section and keep-together rule cannot be bypassed by global splitting');
$large=table($groupEvent,2,$front);$plan=Seating::plan($groupEvent,[]);seatCheck(count($plan['assignments'])===2&&!count($plan['unsatisfied']),'group can be seated together when section has enough space');seatCheck(count(array_diff(array_column($plan['assignments'],'seatId'),array_column($large['seats'],'id')))===0,'group placement stays in the chosen section');
Seating::assign($groupEvent,['layoutRevision'=>$groupEvent['layoutRevision'],'guestId'=>$guestIds[0],'seatId'=>$small['seats'][0]['id'],'locked'=>true]);$plan=Seating::plan($groupEvent,[]);seatCheck(count($plan['assignments'])===0&&count($plan['unsatisfied'])===1,'auto planner does not split a partly assigned keep-together group');
$lookup=Seating::lookup($groupEvent,[$guestIds[0]]);seatCheck($lookup[0]['section']==='Front'&&$lookup[0]['tableNumber']===$small['number'],'guest lookup includes table number and section');
seatReject('GUEST',function()use($groupEvent){$copy=$groupEvent;Seating::saveGroup($copy,['layoutRevision'=>$copy['layoutRevision'],'label'=>'Foreign','guestIds'=>[Support::id()]]);},'guest grouping rejects a guest from another event');
Seating::saveGroup($groupEvent,['layoutRevision'=>$groupEvent['layoutRevision'],'groupId'=>$group['id'],'label'=>'Relatives','guestIds'=>$guestIds,'keepTogether'=>false,'sectionId'=>$front]);seatCheck($groupEvent['guests'][0]['group']==='Relatives'&&count($groupEvent['assignments'])===1,'group rename preserves guests and their assignments');
$plan=Seating::plan($groupEvent,[]);seatCheck(count($plan['assignments'])===1,'explicitly allowing a group to split places its remaining guest');
seatReject('SECTION_OCCUPIED',function()use($groupEvent,$front){$copy=$groupEvent;Seating::saveSection($copy,['layoutRevision'=>$copy['layoutRevision'],'sectionId'=>$front,'delete'=>true]);},'section removal requires an explicit relocation outcome');
Seating::saveSection($groupEvent,['layoutRevision'=>$groupEvent['layoutRevision'],'sectionId'=>$front,'delete'=>true,'moveToUnsectioned'=>true]);seatCheck($groupEvent['tables'][0]['sectionId']===''&&$groupEvent['groups'][0]['sectionId']===''&&count($groupEvent['assignments'])===1,'section removal moves tables and clears placement rules without losing seats');
Seating::saveGroup($groupEvent,['layoutRevision'=>$groupEvent['layoutRevision'],'groupId'=>$group['id'],'label'=>'Relatives','guestIds'=>[],'delete'=>true]);seatCheck(count($groupEvent['groups'])===0&&$groupEvent['guests'][0]['group']===''&&count($groupEvent['assignments'])===1,'removing a group preserves attendees and assignments');
$legacy=seatingEvent();$legacy['tables'][]=['id'=>Support::id(),'label'=>'Family table','shape'=>'round','capacity'=>1,'x'=>200,'y'=>200,'rotation'=>0,'vip'=>false,'seats'=>[['id'=>Support::id(),'label'=>'1','accessible'=>false]]];seatCheck(Seating::viewTables($legacy)[0]['number']===1&&Seating::nextNumber($legacy)===2&&!isset($legacy['tables'][0]['number']),'legacy tables receive consistent display numbers without a read-time write');
$legacy['tables'][0]['label']='Table 7';seatCheck(Seating::viewTables($legacy)[0]['number']===7&&!isset($legacy['tables'][0]['number']),'legacy Table N labels expose their number in the map projection');
$unicode=section($groupEvent,"\u{0DB4}\u{0DC0}\u{0DD4}\u{0DBD}");$asciiKeys=true;foreach(Domain::keys($groupEvent) as $key)if(preg_match('/[^\x00-\x7F]/',$key['value']))$asciiKeys=false;seatCheck($asciiKeys,'Unicode section names remain compatible with database key encoding');
Domain::assertInvariants($groupEvent);seatCheck(true,'extended seating metadata passes aggregate integrity checks');
echo $checks.' seating behavior checks passed.'.PHP_EOL;
